def _copy_site_mode(apps, schema_editor):
    """
    site_mode -> site_templates: marketing -> ['landing'], catalog ->
    ['catalog'], both -> ['landing', 'catalog']. Además resincroniza
    show_catalog con la presencia de 'catalog' (la página apagada
    devuelve 404 igual que antes).
    """
    StoreCustomization  =   apps.get_model('stores', 'StoreCustomization')
    mapping             =   {
        'marketing' :   ['landing'],
        'catalog'   :   ['catalog'],
        'both'      :   ['landing', 'catalog'],
    }
    for row in StoreCustomization.objects.all():
        row.site_templates  =   mapping.get(row.site_mode) or ['landing', 'catalog']
        row.show_catalog    =   'catalog' in row.site_templates
        row.save(update_fields = ['site_templates', 'show_catalog'])


